# Validate reconstructed CP25 outputs.
source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R")); rp_install_and_load(c("dplyr","readr","tibble")); source(file.path(sd_repo_root(),"R","panels","CP25","MANIFEST_RECONSTRUCTED.R")); a<-sd_analysis_dir("CP25"); out<-file.path(a,"validation"); dir.create(out,recursive=TRUE,showWarnings=FALSE)
q<-readr::read_csv(file.path(a,"02_feature_extraction","SDY2583_CP25_feature_extraction_summary_STEP2_RECONSTRUCTED.csv"),show_col_types=FALSE); m<-readr::read_csv(file.path(a,"04_metadata_merge","SDY2583_CP25_metadata_merge_summary_RECONSTRUCTED.csv"),show_col_types=FALSE); st<-readr::read_csv(file.path(a,"06_statistics","SDY2583_CP25_FULL850_age_sex_adjusted_statistics_MAIN_RECONSTRUCTED.csv"),show_col_types=FALSE); sc<-readr::read_csv(file.path(a,"08_composite_scores","SDY2583_CP25_composite_score_statistics_RECONSTRUCTED.csv"),show_col_types=FALSE); mt<-readr::read_csv(file.path(a,"10_age_sensitivity","SDY2583_CP25_age_matched_sensitivity_summary_RECONSTRUCTED.csv"),show_col_types=FALSE); ts<-readr::read_csv(file.path(a,"12_threshold_sensitivity","SDY2583_CP25_threshold_sensitivity_summary_WIDE_RECONSTRUCTED.csv"),show_col_types=FALSE)
near<-function(x,y,t=.02)is.finite(x)&&abs(x-y)<=t*max(1,abs(y)); cls<-table(ts$robust_class)
checks<-tibble::tribble(~check,~observed,~expected,~pass,"files",q$n_files[1],850,q$n_files[1]==850,"success",q$n_success[1],850,q$n_success[1]==850,"median total",q$median_total_events[1],302748,near(q$median_total_events[1],302748,.001),"median raw gate",q$median_raw_cd3cd4_events[1],26488,near(q$median_raw_cd3cd4_events[1],26488,.001),"median primary gate",q$median_primary_events[1],16027,near(q$median_primary_events[1],16027,.001),"valid ages",m$n_valid_age[1],832,m$n_valid_age[1]==832,"main feature count",nrow(st),length(CP25_FEATURES),nrow(st)==length(CP25_FEATURES),"5y pairs",mt$n_pairs[mt$caliper_years==5][1],265,mt$n_pairs[mt$caliper_years==5][1]==265,"10y pairs",mt$n_pairs[mt$caliper_years==10][1],273,mt$n_pairs[mt$caliper_years==10][1]==273,"integrated beta",sc$beta_cancer_vs_healthy[sc$score==CP25_MANIFEST$integrated_score][1],.440,near(sc$beta_cancer_vs_healthy[sc$score==CP25_MANIFEST$integrated_score][1],.440,.02),"targeted outcome count",nrow(ts),73,nrow(ts)==73,"robust direction+FDR",unname(cls["direction_and_FDR_preserved"]),48,unname(cls["direction_and_FDR_preserved"])==48,"direction only",unname(cls["direction_preserved_FDR_not_preserved"]),23,unname(cls["direction_preserved_FDR_not_preserved"])==23,"direction failed",unname(cls["direction_not_preserved"]),2,unname(cls["direction_not_preserved"])==2)
ref<-path.expand(Sys.getenv("SDY2583_CP25_REFERENCE_DIR",unset="")); if(nzchar(ref)&&dir.exists(ref)){pairs<-list(c(file.path(a,"02_feature_extraction","SDY2583_CP25_FULL_850_feature_table_STEP2_RECONSTRUCTED.csv"),"SDY2583_CP25_FULL_850_feature_table_STEP2.csv","subject_id"),c(file.path(a,"06_statistics","SDY2583_CP25_FULL850_age_sex_adjusted_statistics_MAIN_RECONSTRUCTED.csv"),"SDY2583_CP25_FULL850_age_sex_adjusted_statistics_MAIN.csv","module,feature"),c(file.path(a,"08_composite_scores","SDY2583_CP25_composite_score_statistics_RECONSTRUCTED.csv"),"SDY2583_CP25_composite_score_statistics.csv","score")); for(p in pairs){hit<-list.files(ref,p[2],full.names=TRUE,recursive=TRUE,fixed=TRUE); cmp<-if(length(hit))rp_compare_csv(p[1],hit[1],strsplit(p[3],",",fixed=TRUE)[[1]])else tibble::tibble(pass=FALSE,detail="reference missing"); checks<-dplyr::bind_rows(checks,tibble::tibble(check=p[2],observed=cmp$detail[1],expected="table match",pass=cmp$pass[1]))}}
readr::write_csv(checks,file.path(out,"SDY2583_CP25_reconstruction_validation_report.csv")); print(checks,n=nrow(checks)); if(any(!checks$pass))stop("CP25 validation failed.")
